DROP INDEX `collaboration_tasks_pending_workflow`;--> statement-breakpoint
CREATE INDEX `collaboration_tasks_pending_workflow` ON `collaboration_tasks` (`updated_at`,`id`) WHERE "collaboration_tasks"."active" = 1 AND json_extract("collaboration_tasks"."state_json", '$.protocol') = 'native-workflow-v1' AND (json_extract("collaboration_tasks"."state_json", '$.automation') = 'active' OR (json_extract("collaboration_tasks"."state_json", '$.automation') = 'paused' AND json_extract("collaboration_tasks"."state_json", '$.pauseReason') = 'limit' AND json_extract("collaboration_tasks"."state_json", '$.kind') = 'plan' AND json_extract("collaboration_tasks"."state_json", '$.stage') IN ('plan','reply'))) AND json_extract("collaboration_tasks"."state_json", '$.status') IN ('waiting','ready');